/* Standalone browser prototype. All records and operation results are fictional. */
'use strict';
const $ = (s, root = document) => root.querySelector(s);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths = {library:'M4 4h5v16H4z M11 4h4v16h-4z M17 5l3-1 3 15-3 1z',map:'M4 6l5-3 6 3 5-3v15l-5 3-6-3-5 3z M9 3v15 M15 6v15',context:'M5 3h10l4 4v14H5z M14 3v5h5 M8 12h8 M8 16h6',import:'M12 3v12 M7 10l5 5 5-5 M4 15v6h16v-6',health:'M3 12h4l3-8 4 16 3-8h4',settings:'M9 3h6l1 4 4 1 1 6-4 2-1 5h-6l-1-4-5-1-1-6 4-2z M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',arrow:'M5 12h14 M14 7l5 5-5 5',chevron:'M9 6l6 6-6 6',down:'M6 9l6 6 6-6',plus:'M12 5v14 M5 12h14',archive:'M4 8h16v13H4z M3 3h18v5H3z M9 12h6',check:'M5 12l4 4L19 6',link:'M10 14l4-4 M8 16l-2 2a4 4 0 0 1-5-5l5-5a4 4 0 0 1 5 0 M16 8l2-2a4 4 0 0 1 5 5l-5 5a4 4 0 0 1-5 0',more:'M5 12h.01 M12 12h.01 M19 12h.01',close:'M6 6l12 12 M6 18L18 6',note:'M4 4h16v12l-5 5H4z M8 9h8 M8 13h5 M15 21v-5h5',info:'M12 11v6 M12 7h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',sync:'M20 7v5h-5 M4 17v-5h5 M5 8a8 8 0 0 1 14-2l1 3 M4 15l1 3a8 8 0 0 0 14-2',export:'M12 16V3 M7 8l5-5 5 5 M4 14v7h16v-7',back:'M19 12H5 M10 7l-5 5 5 5',expand:'M8 3H3v5 M16 3h5v5 M3 16v5h5 M21 16v5h-5',minus:'M5 12h14',folder:'M3 5h7l2 3h9v13H3z',shield:'M12 2l9 4v6c0 6-9 10-9 10S3 18 3 12V6z M8 12l3 3 5-6'};
const icon = (name) => `<svg class="svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name] || paths.context}"/></svg>`;
const projects = ['Fieldnotes','Atlas research','Commonplace','Little experiments'];
const colors = ['#83a496','#899bc0','#c19e79','#b394ad','#a8b1b6'];
const seeds = [
['Designing a quieter place for our notes','ChatGPT',0,'GPT-4.1','A useful knowledge system should help us return to an idea, not just collect it.','What would a calmer note-taking experience look like? I keep saving things, but finding the original reasoning is still difficult.'],
['Retrieval evaluation: measuring what actually helps','Codex',1,'GPT-5','Separate retrieval quality from answer quality before choosing a metric.','Can we design an evaluation for retrieval that measures evidence usefulness?'],
['A small garden, a seasonal planting plan','ChatGPT',2,'Unknown','A practical plan for the balcony, with room for a little experimentation.','Help me plan a small balcony garden that gets afternoon sunlight.'],
['SQLite migrations without losing local annotations','Codex',0,'GPT-5 · GPT-4.1','Keep source records and local changes in separate tables.','How should we preserve local notes when an imported conversation is updated?'],
['Reading list: attention, memory, and the shape of a good explanation','ChatGPT',1,'GPT-4.1','A reading path from attention to working memory, with questions to explore.','Let’s outline a reading path about attention and memory.'],
['Building an accessible keyboard-first command palette','Codex',3,'GPT-5','Start with predictable focus, clear labels, and an escape route.','What keyboard interactions should our command palette support?'],
['What we meant by “local first”','ChatGPT',0,'GPT-4.1','Local storage is a starting point; inspectability is a separate design choice.','Can you help clarify our local-first design principles?'],
['A weekend field recording kit','ChatGPT',2,'Unknown','A lightweight checklist for listening walks and recording ambient sound.','What should I pack for a weekend of field recordings?'],
['Exploring the tradeoffs of passage-level indexing','Codex',1,'GPT-5','Smaller passages improve precision but can lose the surrounding argument.','Let’s compare message-level and passage-level indexing.'],
['A tiny generative art experiment with circles','Codex',3,'GPT-4.1','Fixed positions and simple transformations can be surprisingly expressive.','I want to try a small browser-based generative art sketch.'],
['How to document uncertainty in research notes','ChatGPT',1,'GPT-4.1','Keep observations, interpretations, and open questions visible.','How can I record uncertainty without making my notes hard to read?'],
['Export formats that stay useful five years from now','Codex',0,'GPT-5','Readable Markdown, stable references, and a plain manifest.','What should a durable conversation export contain?'],
['A better way to organize recipe experiments','ChatGPT',2,'GPT-4.1','Record the small changes that explain the result.','Help me organize the notes from my bread experiments.'],
['Investigating a focus trap in the settings dialog','Codex',3,'GPT-5','Return focus to the triggering control when the dialog closes.','Our settings dialog loses keyboard focus when it closes.'],
['Pilot study protocol and unresolved sampling questions','ChatGPT',1,'GPT-4.1 · GPT-5','A draft protocol with sampling assumptions that need review.','Let’s draft a pilot protocol and make the uncertainties explicit.'],
['What belongs in a project handoff?','ChatGPT',0,'GPT-4.1','Include evidence, current state, and unresolved questions.','What context should I give another assistant to continue a project?'],
['A simple audio waveform viewer','Codex',3,'Unknown','A canvas prototype for exploring short audio clips.','Can we sketch a simple waveform interface?'],
['Walking routes for a slower Sunday','ChatGPT',2,'GPT-4.1','A few ways to make a familiar neighborhood feel new.','Help me make a loose plan for a long Sunday walk.'],
['Comparing annotation schemas for the pilot corpus','Codex',1,'GPT-5','Use a small agreement sample before expanding the annotation scheme.','How should we compare two annotation schemes?'],
['Keeping original source text intact on reimport','Codex',0,'GPT-5','Stable source identities keep imports idempotent.','How do we avoid duplicate records when importing the same export?'],
['A color study in sage and slate','ChatGPT',3,'GPT-4.1','A compact palette for quiet interfaces.','Let’s explore a color palette for a reading app.'],
['Notes on making a good index','ChatGPT',2,'Unknown','An index is a set of useful routes back to the material.','What makes an index useful rather than merely comprehensive?'],
['Writing a reproducible search benchmark','Codex',1,'GPT-5','Freeze the corpus, queries, judgments, and retrieval settings.','Help me outline a reproducible search benchmark.'],
['A prototype we chose to set aside','Codex',0,'GPT-4.1','Archived locally: the original discussion is preserved.','Let’s record why we set this interface prototype aside.']
];
let saved = {};try { saved = JSON.parse(localStorage.getItem('smriti-fictional-demo-v1') || '{}'); } catch {}
const records = seeds.map((s,i)=>({id:i+1,title:s[0],source:s[1],project:s[2],model:s[3],excerpt:s[4],prompt:s[5],date:`Oct ${27-Math.floor(i/2)}, 2026`,partial:[4,8,16].includes(i),unclustered:[7,16,21].includes(i),archived:i===23,...saved[i+1]}));
const state={view:'library',selected:1,q:'',source:'All sources',project:'All projects',archive:false,page:1,size:10,sort:'recent',mode:'keyword',mobileReader:false,topic:null,labels:true,unclustered:true,zoom:1,panX:0,panY:0,selectedMap:new Set(),contextTab:'review',syncing:false,scenario:'normal',density:'comfortable',match:0};
const contexts=[{title:'Fieldnotes · project context',scope:'Fieldnotes',status:'Awaiting review',body:'Fieldnotes is a fictional personal knowledge project. The current prototype uses readable files and a local database. Open questions: which fields belong in the portable manifest, and how should partial source captures be represented?',sources:'Designing a quieter place for our notes; Export formats that stay useful five years from now',uncertainty:'These are discussion notes. The export format is still a proposal.'},{title:'Research writing preferences',scope:'Atlas research',status:'Accepted',body:'Keep observations separate from interpretations. Include source references and unresolved assumptions in research notes.',sources:'How to document uncertainty in research notes',uncertainty:'Applies only to this fictional research project.'}];
function persist(){try{localStorage.setItem('smriti-fictional-demo-v1',JSON.stringify(Object.fromEntries(records.map(r=>[r.id,{localTitle:r.localTitle,note:r.note,project:r.project,archived:r.archived}]))));}catch{toast('Browser storage is unavailable. Changes last for this session.');}}
function toast(message){const t=$('#toast');t.textContent=message;t.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.style.display='none',4200);}
function displayTitle(r){return r.localTitle || r.title;}
function fullText(r){return `${r.title} ${r.localTitle||''} ${r.note||''} ${r.prompt} ${r.excerpt} ${r.id===1 ? 'The best interface feels like a well-kept reading room. Give each conversation a stable home. A conversation is the evidence; a note is your interpretation. Keep the original wording intact, then give local annotations a separate place. Let the library stay familiar. Lead with recency and useful excerpts. Make returning to a particular passage effortless. Preserve a way back. An export should retain source references and uncertainty. A small starting point. source_id local_title source_messages annotations' : 'Keep the original evidence and local notes separate. This is a fictional sample conversation for interface testing. The next step is to test this idea on a small example and record the limitations.'}`;}
function filtered(map=false){if(state.scenario==='empty')return [];return records.filter(r=>(map||r.archived===state.archive)&&(state.source==='All sources'||r.source===state.source)&&(state.project==='All projects'||projects[r.project]===state.project)&&(!state.q||fullText(r).toLowerCase().includes(state.q.toLowerCase()))&&(state.scenario!=='no-results')).sort((a,b)=>state.sort==='title'?displayTitle(a).localeCompare(displayTitle(b)):a.id-b.id);}
function highlight(s){if(!state.q)return esc(s);const parts=String(s).split(new RegExp(`(${state.q.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')})`,'ig'));return parts.map((p,i)=>i%2?`<mark>${esc(p)}</mark>`:esc(p)).join('');}
function nav(name,label,count){return `<button class="nav-btn ${state.view===name?'active':''}" data-view="${name}" ${state.view===name?'aria-current="page"':''} title="${label}">${icon(name)}<span>${label}</span>${count!==undefined?`<span class="count">${count}</span>`:''}</button>`;}
function render(){const labels={library:state.archive?'Archive':'Conversation library',map:'Conversation map',context:'Context & snapshots',import:'Import & sources',health:'Workspace health',settings:'Settings'};$('#app').innerHTML=`<div class="layout"><aside class="sidebar"><div class="brand"><svg class="brand-mark" viewBox="0 0 38 42" fill="none" aria-hidden="true"><path d="M30 8H13L5 16l21 12-8 8H5 M33 6L10 29 M33 16L13 36 M31 7l3 7-7 7L8 10l-4 7 27 16-4 6" stroke="white" stroke-width="2.6" stroke-linejoin="round"/></svg><span class="brand-name">smriti</span></div><div class="workspace"><span class="avatar">E</span><span class="workspace-name">Ellis’s workspace<small>Personal · local</small></span>${icon('down')}</div><div class="nav-label">Workspace</div>${nav('library','Conversations',records.filter(r=>!r.archived).length)}${nav('map','Conversation map')}${nav('context','Context & snapshots')}<div class="nav-label">Projects</div>${projects.map((p,i)=>`<button class="project-nav" data-project="${i}"><span class="dot" style="background:${colors[i]}"></span>${p}</button>`).join('')}<div class="side-bottom">${nav('import','Import & sources')}${nav('health','Workspace health')}${nav('settings','Settings')}<div class="local-status"><span class="dot"></span>Local workspace <span style="margin-left:auto">${icon('shield')}</span></div></div></aside><main class="main"><header class="topbar"><div class="crumb">Workspace ${icon('chevron')}<strong>${labels[state.view]}</strong></div><div class="top-actions"><span class="demo-badge">Fictional demo</span><span class="last-sync">${state.synced?'Demo sync complete':'Last sync 12 minutes ago'}</span><button class="ghost sync" data-action="sync" ${state.syncing?'disabled':''}>${icon('sync')}${state.syncing?'Syncing…':'Sync now'}</button><button class="ghost icon" title="Workspace details" data-action="workspace">${icon('info')}</button></div></header>${state.view==='library'?library():state.view==='map'?mapView():state.view==='context'?contextView():state.view==='import'?importView():state.view==='health'?healthView():settingsView()}<div class="footer-note">A little less searching. A little more remembering. <span style="margin:0 8px">·</span> Interactive prototype · fictional records only</div></main></div>`;bind();}
function heading(title,description,action=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${description}</p></div>${action}</div>`;}
function toolbar(map=false){return `<div class="toolbar"><label class="search" aria-label="Search conversations">${icon('search')}<input id="search" placeholder="${map?'Find a conversation or idea…':'Search your conversations…'}" value="${esc(state.q)}"><kbd>⌘ K</kbd></label><select id="source" aria-label="Filter by source">${['All sources','ChatGPT','Codex'].map(p=>`<option ${state.source===p?'selected':''}>${p}</option>`).join('')}</select><select id="project" aria-label="Filter by project">${['All projects',...projects].map(p=>`<option ${state.project===p?'selected':''}>${p}</option>`).join('')}</select>${!map?`<div class="search-mode" aria-label="Search mode"><button data-mode="keyword" class="${state.mode==='keyword'?'active':''}">Keyword</button><button data-mode="smart" class="${state.mode==='smart'?'active':''}">✧ Smart</button></div>`:''}</div>`;}
function library(){const all=filtered();const start=(state.page-1)*state.size;const list=all.slice(start,start+state.size);let r=records.find(x=>x.id===state.selected);if(!list.some(x=>x.id===r?.id)&&list.length){r=list[0];state.selected=r.id;}return heading(state.archive?'Your archive':'Your conversations','Good ideas deserve a way back.',`<button data-action="import">${icon('plus')} Import conversations</button>`)+toolbar()+`<div class="library-grid ${state.mobileReader?'show-reader':''}"><section class="results" aria-label="Conversation results"><div class="result-top"><span>${all.length} ${state.q?'matching ':''}conversations</span><select id="sort" aria-label="Sort conversations"><option value="recent">Most recent</option><option value="title" ${state.sort==='title'?'selected':''}>Title A–Z</option></select></div>${state.mode==='smart'?`<div class="empty">${icon('search')}<h2>Find related ideas</h2><p>Smart search needs local models.<br>Keyword search is ready to use.</p><button data-view="settings">Set up smart search ${icon('arrow')}</button><span class="small muted">Experimental · no models run in this demo</span></div>`:list.length?list.map(conversationRow).join(''):`<div class="empty">${icon('library')}<h2>${state.scenario==='empty'?'A place for your conversations':'Nothing here just yet'}</h2><p>${state.q?'Try different words or clear your filters.':state.archive?'Archived conversations will appear here.':'Import an export to start your library.'}</p><button data-action="${state.scenario==='empty'?'import':'clear'}">${state.scenario==='empty'?'Import conversations':'Clear filters'}</button></div>`}</section><article class="reader" aria-label="Conversation reader">${all.length&&state.mode==='keyword'?reader(r):`<div class="empty">${icon('context')}<h2>A conversation worth returning to</h2><p>Select a conversation to read the original messages.</p></div>`}</article></div><div class="pagination"><span>${all.length?`${start+1}–${Math.min(start+state.size,all.length)}`:'0'} of ${all.length} conversations <button class="ghost" data-action="archive-list">${state.archive?'Active library':'View archive'} ${icon('arrow')}</button></span><div class="pages"><label>Per page <select id="size" aria-label="Records per page">${[10,50,100].map(n=>`<option ${state.size===n?'selected':''}>${n}</option>`).join('')}</select></label><button data-action="prev" ${state.page===1?'disabled':''} aria-label="Previous page">‹</button><span>${state.page} / ${Math.max(1,Math.ceil(all.length/state.size))}</span><button data-action="next" ${start+state.size>=all.length?'disabled':''} aria-label="Next page">›</button></div></div>`;}
function conversationRow(r){return `<button class="conversation ${state.selected===r.id?'selected':''}" data-record="${r.id}" aria-pressed="${state.selected===r.id}"><div class="conv-meta"><span class="source-mark ${r.source==='Codex'?'codex':''}">${r.source==='Codex'?'⌘':'❋'}</span>${r.source}<time>${r.date.replace(', 2026','')}</time></div><div class="conv-title">${highlight(displayTitle(r))}</div><p class="excerpt">${highlight(state.q&&r.note?.toLowerCase().includes(state.q.toLowerCase())?`Local note: ${r.note}`:r.excerpt)}</p><div class="conv-bottom"><span class="pill"><span class="dot" style="background:${colors[r.project]}"></span>${projects[r.project]}</span>${r.partial?'<span class="pill amber">Partial</span>':''}<span class="model">${r.model==='Unknown'?'Model unknown':esc(r.model)}</span></div></button>`;}
function reader(r){const special=r.id===1;return `<div class="reader-tools"><div class="left"><button class="ghost back-list" data-action="back" aria-label="Back to results">${icon('back')}</button><span class="eyebrow">Conversation</span><span class="pill green" style="margin-left:9px">${r.partial?'Partial capture':'Captured'}</span></div><div class="right"><button class="ghost" data-action="notes" aria-label="Edit local annotations">${icon('note')}<span>Local notes${r.note?' · 1':''}</span></button><button class="ghost" data-action="export-one" aria-label="Export conversation">${icon('export')}<span>Export</span></button><button class="ghost icon" data-action="details" title="Capture details">${icon('more')}</button></div></div><div class="reader-header"><span class="eyebrow">${r.source} <span style="margin:0 6px">/</span> ${r.date}</span><h2>${highlight(displayTitle(r))}</h2><div class="reader-info"><span>${r.partial?'3 captured messages':'4 messages'}</span><span>·</span><span>${r.model==='Unknown'?'Model not captured':esc(r.model)}</span><span>·</span><span class="pill"><span class="dot" style="background:${colors[r.project]}"></span>${projects[r.project]}</span></div>${r.localTitle?`<div class="muted small" style="margin-top:8px">Source title: ${esc(r.title)}</div>`:''}${r.note?`<div class="note-preview">Local note: ${esc(r.note)}</div>`:''}</div>${r.partial?'<div class="notice">Partial history · One assistant reply and an attachment were unavailable. Missing content is not included below.</div>':''}${state.q?`<div class="match-bar"><span>Matches highlighted in captured text and local annotations.</span><button class="ghost" data-action="match-prev" aria-label="Previous match">↑</button><button class="ghost" data-action="match-next" aria-label="Next match">↓</button></div>`:''}<div class="reader-message"><div class="message-by"><span class="message-avatar">E</span><strong>You</strong><time>10:42 AM</time></div><div class="message-body"><p>${highlight(r.prompt)}</p></div></div><div class="reader-message"><div class="message-by"><span class="message-avatar">${r.source==='Codex'?'⌘':'❋'}</span><strong>${r.source}</strong><span class="muted" style="font-size:9px">${esc(r.model==='Unknown'?'Model unknown':r.model.split(' · ')[0])}</span><time>10:43 AM</time></div><div class="message-body">${special?`<p>${highlight('The best interface feels like a well-kept reading room. It gives you a place to begin, enough context to recognize something, and space to stay with it.')}</p><h3>${highlight('Give each conversation a stable home.')}</h3><p>${highlight('A conversation is the evidence; a note is your interpretation. Keep the original wording intact, then give local annotations a separate place. That distinction makes it easier to trust what you find later.')}</p><h3>${highlight('Let the library stay familiar.')}</h3><ul><li>${highlight('Lead with recency and useful excerpts.')}</li><li>${highlight('Make returning to a particular passage effortless.')}</li><li>${highlight('Keep project associations lightweight and reversible.')}</li></ul><h3>${highlight('Preserve a way back.')}</h3><p>${highlight('An export should retain source references and uncertainty. A good handoff gives the next assistant evidence to inspect, alongside the questions that remain open.')}</p><pre>${highlight('conversation\n  ├─ source_id\n  ├─ source_messages\n  └─ annotations\n       ├─ local_title\n       └─ notes')}</pre>`:`<p>${highlight(r.excerpt)}</p><p>${highlight('Keep the original evidence and local notes separate. This is a fictional sample conversation for interface testing.')}</p><h3>A small starting point</h3><p>${highlight('The next step is to test this idea on a small example and record the limitations. This discussion is a proposal and does not establish an accepted decision.')}</p>`}<div class="evidence">${icon('link')} Original captured message <span>·</span><button class="ghost" data-action="details" style="font-size:9px;padding:0">View source details ${icon('arrow')}</button></div></div></div><div class="reader-message"><div class="message-by"><span class="message-avatar">E</span><strong>You</strong><time>10:46 AM</time></div><div class="message-body"><p>Let’s keep that distinction visible in the prototype.</p></div></div>${r.partial?'<div class="notice" style="margin-bottom:24px">Assistant reply unavailable in this capture.</div>':`<div class="reader-message"><div class="message-by"><span class="message-avatar">❋</span><strong>${r.source}</strong><time>10:47 AM</time></div><div class="message-body"><p>We can try that in a small example and review it together.</p></div></div>`}`;}
function mapView(){const list=filtered(true).filter(r=>(state.topic===null||r.project===state.topic)&&(state.unclustered||!r.unclustered));return heading('Follow a thread','A different way to find what connects your conversations.',`<button data-action="handoff">${icon('export')} Prepare handoff${state.selectedMap.size?` · ${state.selectedMap.size}`:''}</button>`)+toolbar(true)+`<div class="content"><div class="inline-actions" style="margin-bottom:15px">${['All topics',...projects].map((p,i)=>`<button data-topic="${i-1}" class="${state.topic===i-1||i===0&&state.topic===null?'primary':''}" style="font-size:10px">${i?`<span class="dot" style="background:${colors[i-1]}"></span>`:''}${p}</button>`).join('')}<button class="ghost" data-action="map-options">${icon('settings')} Display</button></div><div class="map-layout"><div class="map-canvas" id="map-canvas"><div class="map-top"><span>Illustrative topic map · ${list.length} conversations</span><span>Fixed sample positions · no clustering</span></div><svg id="topic-map" viewBox="0 0 800 600" aria-label="Fictional conversation map; all points also appear in the results list"><g transform="translate(${400+state.panX},${300+state.panY}) scale(${state.zoom}) translate(-400,-300)">${list.map(r=>{const c=r.unclustered?4:r.project;const centers=[[240,180],[540,200],[255,420],[560,430],[410,315]];const [x,y]=centers[c];const angle=r.id*2.4;const radius=state.density==='compact'?27:47;const px=x+Math.cos(angle)*(radius+r.id%4*13),py=y+Math.sin(angle)*(radius+r.id%3*12);return `<circle tabindex="0" role="button" aria-label="${esc(displayTitle(r))}" data-point="${r.id}" cx="${px}" cy="${py}" r="${r.id===state.selected?10:7}" fill="${colors[c]}" opacity="${r.unclustered?'.8':.6+(r.id%4)*.1}" class="${state.selectedMap.has(r.id)||state.selected===r.id?'chosen':''}"><title>${esc(displayTitle(r))}</title></circle>`;}).join('')}${state.labels?projects.map((p,i)=>{const xy=[[175,90],[490,98],[190,520],[502,535]][i];return `<text tabindex="0" role="button" aria-label="Focus ${p}" class="map-label" x="${xy[0]}" y="${xy[1]}" data-topic="${i}">${p}</text>`;}).join(''):''}</g></svg><div class="map-controls"><button class="icon" data-action="zoom-in" aria-label="Zoom in">${icon('plus')}</button><button class="icon" data-action="zoom-out" aria-label="Zoom out">${icon('minus')}</button><button class="icon" data-action="fit" aria-label="Fit map">${icon('expand')}</button><button class="icon" data-action="expand" aria-label="Expand map">${icon('map')}</button></div><div class="map-legend"><span><span class="dot" style="background:#9facb3"></span> Unclustered</span><button class="ghost" style="padding:0;font-size:9px" data-action="map-info">About this map ${icon('info')}</button></div></div><aside class="map-results"><h3>${state.topic===null?'Conversations':projects[state.topic]} <span class="muted small">${list.length}</span></h3>${list.length?list.map(r=>`<div class="map-result"><input type="checkbox" data-map-check="${r.id}" aria-label="Select ${esc(displayTitle(r))} for export" ${state.selectedMap.has(r.id)?'checked':''}><div><button data-record="${r.id}" title="Read conversation">${esc(displayTitle(r))}</button><p>${r.source} · ${r.date}${r.archived?' · Archived':''}</p><span class="pill">${r.unclustered?'Unclustered':projects[r.project]}</span></div></div>`).join(''):'<div class="empty">No conversations match these filters.</div>'}</aside></div><div class="help-block">Positions are illustrative, and colors represent sample topic groups. Opacity illustrates membership strength, not confidence. Select points to prepare a handoff, or open a conversation from the list. <button class="ghost" data-action="export-map" style="font-size:10px">Export map SVG ${icon('export')}</button><button class="ghost" data-action="export-map-data" style="font-size:10px">Export results ${icon('export')}</button></div></div>`;}
function contextView(){return heading('Context, with a source','Review what travels with your work.',`<button data-action="context-import">${icon('plus')} Import context</button>`)+`<div class="content"><div class="tabs">${[['review','Reusable context'],['skills','Skills'],['memory','Memory'],['instructions','Instructions']].map(([id,label])=>`<button data-context-tab="${id}" class="${state.contextTab===id?'active':''}">${label}</button>`).join('')}</div>${state.contextTab==='review'?`<div class="help-block" style="margin-top:0;margin-bottom:22px">Context is reviewed separately from source conversations. Acceptance makes it eligible for retrieval and optional export. It does not activate an assistant integration.</div><div class="rows">${contexts.map((c,i)=>`<div class="data-row"><div><strong>${esc(c.title)}</strong><p>${esc(c.scope)} · ${i+1} source references · Fictional artifact</p></div><div class="actions"><span class="pill ${c.status==='Accepted'?'green':c.status==='Retired'?'':'amber'}">${esc(c.status)}</span><button data-review="${i}">Review ${icon('arrow')}</button></div></div>`).join('')}</div>`:`<div class="help-block" style="margin-top:0;margin-bottom:22px">Captured copies for inspection. These fictional snapshots are not live assistant configuration and do not indicate activation.</div><div class="rows">${[1,2,3].map((n)=>`<div class="data-row"><div><strong>${state.contextTab==='skills'?['Research handoff','Source inspection','Project resumption'][n-1]:state.contextTab==='memory'?['Project preferences','Research scope','Writing conventions'][n-1]:['Project instructions','Workspace access guide','Evidence handling'][n-1]}</strong><p>/fictional/workspace/${state.contextTab}/snapshot-${n}.md · Captured Oct 26, 2026</p></div><button data-snapshot="${n}">Inspect ${icon('arrow')}</button></div>`).join('')}</div>`}</div>`;}
function importView(){return heading('Bring your conversations home','Your sources, gathered in one inspectable workspace.',`<button data-action="import">${icon('plus')} Import export</button>`)+`<div class="content"><div class="cards"><div class="card">${icon('import')}<h3 style="margin-top:16px">ChatGPT exports</h3><p>Import a JSON or ZIP export. Stable source identities help avoid duplicate conversations.</p><button data-action="import">Choose a file ${icon('arrow')}</button></div><div class="card">${icon('folder')}<h3 style="margin-top:16px">Local Codex history</h3><p>Choose a source directory explicitly. Available local history may have gaps.</p><button data-action="source">Configure source ${icon('arrow')}</button></div><div class="card">${icon('context')}<h3 style="margin-top:16px">Assistant access</h3><p>Prepare an access guide for your existing assistant. Review and provide it yourself.</p><button data-action="guide">Prepare guide ${icon('arrow')}</button></div></div><h3 class="section-title">Configured sample sources</h3><div class="rows"><div class="data-row"><div><strong>ChatGPT export inbox</strong><p>Last received Oct 27 · 12 fictional conversations · 2 partial captures</p></div><span class="pill green">Up to date</span></div><div class="data-row"><div><strong>Codex · local history</strong><p>${esc(state.sourcePath||'/fictional/ellis/codex-history')} · 12 fictional records</p></div><span class="pill amber">Some history unavailable</span></div></div><div class="help-block">This UI demo never reads local history or connects accounts. File validation happens in your browser; imports are not added to a real database. ZIP attachment recovery is not complete.</div><h3 class="section-title">Portable collection</h3><div class="card wide-card"><h3>Continue the work somewhere else</h3><p>Export readable conversations, separate annotations, and optional accepted context. Review the files before providing them to another application.</p><button data-action="bundle">${icon('export')} Prepare a portable bundle</button></div></div>`;}
function healthView(){return heading('A clear view of your workspace','Capture quality and database health are different things.',`<button data-action="health-check">${icon('health')} Run health check</button>`)+`<div class="content"><div class="cards"><div class="card"><div><span class="eyebrow">Conversations</span><div class="big-number">${records.length}</div><p>Across 2 sample sources</p></div><span class="pill green">${records.filter(r=>r.archived).length} archived locally</span></div><div class="card"><div><span class="eyebrow">Database</span><div class="big-number">Healthy</div><p>Sample integrity check passed</p></div>${icon('shield')}</div><div class="card"><div><span class="eyebrow">Capture coverage</span><div class="big-number">3 partial</div><p>Some original content unavailable</p></div><span class="pill amber">Known gaps</span></div></div><h3 class="section-title">Sync activity</h3><div class="rows"><div class="data-row"><div><strong>${state.synced?'Demo sync complete':'Last sample sync · Oct 27, 10:30 AM'}</strong><p>2 new · 3 updated · 0 duplicate records · 3 partial captures</p></div><button data-action="sync" ${state.syncing?'disabled':''}>${icon('sync')} ${state.syncing?'Syncing…':'Sync now'}</button></div><div class="data-row"><div><strong>Source coverage</strong><p>One missing reply, two metadata gaps, and one unavailable attachment in sample captures.</p></div><span class="pill amber">Partial histories</span></div></div><h3 class="section-title">Local backup</h3><div class="card wide-card"><h3>${state.backedUp?'Demo backup downloaded':'Keep a copy of your database'}</h3><p>A database backup includes local annotations. It does not include every attachment, source file, or assistant configuration.</p><button data-action="backup">${icon('export')} Create demo backup</button><div class="small muted" style="margin-top:12px">Prototype backup: JSON containing fictional records and their local annotations.</div></div></div>`;}
function settingsView(){return heading('Make room for your way of working','Basic browsing and keyword search work without local AI models.')+`<div class="content"><div class="settings-grid"><div class="card"><span class="pill amber">Not configured</span><h2 style="margin-top:18px">Smart search</h2><p>Find related ideas even when the words are different. Choose local models, then index your passages.</p><div class="field"><label for="embedding">Embedding model</label><select id="embedding"><option>Small local embedding model · sample</option><option>Multilingual embedding model · sample</option></select><small>Illustrative choices; this prototype does not download or run models.</small></div><div class="field"><label for="reranker">Reranking model</label><select id="reranker"><option>Small local reranker · sample</option><option>No reranker</option></select></div><div class="inline-actions"><button data-action="model-demo">Preview model download</button><button data-action="index-demo" ${state.modelReady?'':'disabled'}>Preview indexing</button></div>${state.modelReady?'<div class="help-block">Sample model readiness: ready. No model was downloaded.</div>':''}<div class="help-block">Experimental similarity helps discover related passages. It does not establish agreement, accuracy, or a confirmed decision.</div></div><div><div class="card"><h3>Prototype states</h3><p>Try empty, failure, and normal states without changing the sample data.</p><div class="field"><label for="scenario">Library scenario</label><select id="scenario">${[['normal','Populated workspace'],['empty','New empty workspace'],['no-results','No matching results'],['sync-failure','Sync failure']].map(([v,t])=>`<option value="${v}" ${state.scenario===v?'selected':''}>${t}</option>`).join('')}</select></div><button data-view="library">Open library ${icon('arrow')}</button></div><div class="card" style="margin-top:20px"><h3>About this prototype</h3><p>All conversations, paths, timestamps, and operation results are fictional. Local titles, notes, and archive changes are stored in this browser.</p><button data-action="reset">Reset demo data</button></div></div></div></div>`;}
function modal(title,body,foot=''){const d=$('#dialog');d.innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="ghost icon" data-close aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${body}</div>${foot?`<div class="modal-foot">${foot}</div>`:''}`;d.querySelectorAll('[data-close]').forEach(el=>el.onclick=()=>d.close());if(!d.open)d.showModal();return d;}
function download(name,content,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);}
function exportRecords(list,accepted=false){download('smriti-fictional-collection.json',JSON.stringify({format:'smriti-ui-demo-v1',fictional:true,createdAt:new Date().toISOString(),sourceRecords:list.map(r=>({id:`fictional-${r.id}`,title:r.title,source:r.source,model:r.model,partial:r.partial,messages:[{speaker:'user',text:r.prompt},{speaker:'assistant',text:r.excerpt}]})),localAnnotations:list.map(r=>({id:`fictional-${r.id}`,title:r.localTitle||null,note:r.note||'',project:projects[r.project],archived:r.archived})),context:accepted?contexts.filter(c=>c.status==='Accepted'):[],limitations:'Fictional prototype export. Contains sample message text, not a real complete capture. No integrity certification.'},null,2));toast(`Exported ${list.length} fictional conversations with separate annotations.`);}
function showImport(){const d=modal('Import conversations',`<p>Choose a ChatGPT JSON or ZIP export. Demo limit: 20 MB. Importing a file does not connect an account.</p><label class="dropzone" id="dropzone">${icon('import')}<strong>Choose an export, or drop it here</strong><p>JSON or ZIP · up to 20 MB</p><input type="file" id="import-file" accept=".json,.zip" aria-label="Choose ChatGPT export"></label><div id="import-status" style="margin-top:16px" aria-live="polite"></div><p style="margin-top:16px;font-size:10px">Browser-only validation. No file is uploaded or added to a real database.</p>`,`<button data-close>Done</button>`);const validate=async file=>{const status=$('#import-status',d);if(!file)return;if(file.size>20*1024*1024){status.innerHTML='<div class="error">File exceeds the 20 MB demo limit. Choose a smaller export.</div>';return;}status.textContent='Validating file…';try{const ext=file.name.split('.').pop().toLowerCase();if(!['json','zip'].includes(ext))throw Error('Unsupported file. Choose a JSON or ZIP export.');if(ext==='json'){const json=JSON.parse(await file.text());if(!Array.isArray(json)&&!Array.isArray(json.conversations))throw Error('Expected a conversation array or an object containing conversations.');const n=Array.isArray(json)?json.length:json.conversations.length;status.innerHTML=`<div class="success">Valid JSON structure · ${n} candidate records. Preview only; no records were imported. A real import would validate source identities, handle duplicates, then sync.</div>`;}else{const header=new Uint8Array(await file.slice(0,4).arrayBuffer());if(header[0]!==80||header[1]!==75)throw Error('This file does not have a ZIP header.');status.innerHTML='<div class="success">ZIP header recognized. Archive contents are not inspected in this prototype; no records imported.</div>';}}catch(e){status.innerHTML=`<div class="error">${esc(e.message)}</div>`;}};$('#import-file',d).onchange=e=>validate(e.target.files[0]);const zone=$('#dropzone',d);zone.ondragover=e=>e.preventDefault();zone.ondrop=e=>{e.preventDefault();validate(e.dataTransfer.files[0]);};}
function showNotes(){const r=records.find(r=>r.id===state.selected);const d=modal('Your local annotations',`<p>Keep your interpretation alongside the source. Changes apply only in this prototype.</p><div class="field"><label for="local-title">Local title</label><input id="local-title" value="${esc(r.localTitle||'')}" placeholder="${esc(r.title)}"><small>Original source title stays intact.</small></div><div class="field"><label for="local-note">Notes</label><textarea id="local-note" placeholder="What would you like to remember?">${esc(r.note||'')}</textarea></div><div class="field"><label for="local-project">Project</label><select id="local-project">${projects.map((p,i)=>`<option value="${i}" ${r.project===i?'selected':''}>${p}</option>`).join('')}</select></div>`,`<button id="archive-record">${icon('archive')} ${r.archived?'Restore':'Archive locally'}</button><button data-close>Cancel</button><button class="primary" id="save-notes">Save annotations</button>`);$('#save-notes',d).onclick=()=>{r.localTitle=$('#local-title',d).value.trim();r.note=$('#local-note',d).value.trim();r.project=Number($('#local-project',d).value);persist();d.close();render();toast('Local annotations saved. Source text preserved.');};$('#archive-record',d).onclick=()=>{r.archived=!r.archived;persist();d.close();render();toast(r.archived?'Conversation archived locally. Find it in View archive.':'Conversation restored to the active library.');};}
function showDetails(){const r=records.find(r=>r.id===state.selected);modal('Capture & source details',`<dl class="details-list"><dt>Source title</dt><dd>${esc(r.title)}</dd><dt>Source application</dt><dd>${r.source}</dd><dt>Source identity</dt><dd>fictional-${r.source.toLowerCase()}-${String(r.id).padStart(4,'0')}</dd><dt>Captured</dt><dd>${r.date}, 10:50 AM · sample timestamp</dd><dt>Observed models</dt><dd>${esc(r.model==='Unknown'?'Not captured; unknown':r.model)}</dd><dt>Completeness</dt><dd>${r.partial?'Partial. One reply and an attachment unavailable.':'All four sample messages shown.'}</dd><dt>Branch</dt><dd>${r.id===4?'Fictional branch of conversation demo-0002':'Branch relationship unknown'}</dd><dt>Source path</dt><dd>/fictional/ellis/imports/conversation-${r.id}.json</dd></dl><div class="help-block">Source paths and metadata are fictional. Captured text is displayed as content and never executed.</div>`,`<button data-close>Close</button>`);}
function showBundle(){const d=modal('Prepare a portable collection',`<p>Download fictional source records and separate local annotations. Nothing is uploaded or installed into another assistant.</p><div class="field"><label for="bundle-scope">Include conversations</label><select id="bundle-scope"><option value="all">All conversations, including archived</option><option value="one">Current conversation</option>${projects.map((p,i)=>`<option value="${i}">${p}</option>`).join('')}</select></div><label class="check"><input type="checkbox" id="bundle-context">Include accepted reusable context</label><div class="help-block">Prototype export: one readable JSON file. Source metadata, known gaps, and local annotations are included. This demo does not generate a production verified bundle.</div>`,`<button data-close>Cancel</button><button class="primary" id="download-bundle">${icon('export')} Download collection</button>`);$('#download-bundle',d).onclick=()=>{const scope=$('#bundle-scope',d).value;exportRecords(scope==='all'?records:scope==='one'?records.filter(r=>r.id===state.selected):records.filter(r=>r.project===Number(scope)),$('#bundle-context',d).checked);d.close();};}
function showHandoff(){const selected=records.filter(r=>state.selectedMap.has(r.id));const list=selected.length?selected:filtered(true).filter(r=>state.topic===null||r.project===state.topic);const body=`# smriti · fictional conversation handoff\n\nReview the source passages below. Distinguish proposals from accepted decisions, and preserve uncertainty. This is a UI prototype with fictional records.\n\n${list.map(r=>`## ${displayTitle(r)}\nSource: ${r.source} / fictional-${r.id}\nCapture: ${r.partial?'partial':'sample messages'}\nUser: ${r.prompt}\nAssistant: ${r.excerpt}\nLocal note: ${r.note||'None'}\n`).join('\n')}\nAccess: this handoff contains the sample excerpts. No source account or assistant connection is configured.\n`;const d=modal('A handoff you can inspect',`<p>${list.length} fictional conversations selected. Review the passages before giving this file to your existing assistant.</p><div class="context-body" style="max-height:270px;overflow:auto;white-space:pre-wrap">${esc(body)}</div>`,`<button data-close>Cancel</button><button class="primary" id="download-handoff">Download handoff</button>`);$('#download-handoff',d).onclick=()=>{download('smriti-fictional-handoff.md',body,'text/markdown');d.close();toast('Handoff downloaded. Provide it to your assistant when ready.');};}
function reviewContext(i){const c=contexts[i];const d=modal(esc(c.title),`<span class="pill ${c.status==='Accepted'?'green':'amber'}">${esc(c.status)}</span><h3 style="margin-top:18px">Artifact body</h3><div class="context-body">${esc(c.body)}</div><h3 style="margin-top:20px">Sources & scope</h3><p>${esc(c.sources)}<br>Scope: ${esc(c.scope)}</p><h3>Uncertainty</h3><p>${esc(c.uncertainty)}</p>${c.reason?`<h3>Retirement reason</h3><p>${esc(c.reason)}</p>`:''}${c.status==='Accepted'?'<div class="field"><label for="retire-reason">Reason for retirement</label><input id="retire-reason" placeholder="Why is this context no longer current?"></div>':''}`,`<button data-close>Close</button>${c.status==='Awaiting review'?'<button class="primary" id="accept-context">Accept context</button>':c.status==='Accepted'?'<button id="retire-context">Retire context</button>':''}`);if($('#accept-context',d))$('#accept-context',d).onclick=()=>{c.status='Accepted';d.close();render();toast('Context accepted for this demo session.');};if($('#retire-context',d))$('#retire-context',d).onclick=()=>{const reason=$('#retire-reason',d).value.trim();if(!reason){$('#retire-reason',d).focus();toast('Add a retirement reason to preserve review history.');return;}c.reason=reason;c.status='Retired';d.close();render();toast('Context retired and excluded from future demo exports.');};}
function bind(){document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{state.view=b.dataset.view;state.mobileReader=false;render();});document.querySelectorAll('[data-project]').forEach(b=>b.onclick=()=>{state.project=projects[Number(b.dataset.project)];state.view='library';state.page=1;render();});document.querySelectorAll('[data-record]').forEach(b=>b.onclick=()=>{const r=records.find(r=>r.id===Number(b.dataset.record));state.selected=r.id;state.archive=r.archived;state.view='library';state.page=1;const list=filtered();if(!list.some(x=>x.id===r.id)){state.q='';state.source='All sources';state.project='All projects';}const idx=filtered().findIndex(x=>x.id===r.id);state.page=Math.floor(Math.max(0,idx)/state.size)+1;state.mode='keyword';state.mobileReader=true;render();});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{state.mode=b.dataset.mode;render();});const search=$('#search');if(search)search.oninput=e=>{const pos=e.target.selectionStart;state.q=e.target.value;state.page=1;state.mobileReader=false;render();$('#search').focus();$('#search').setSelectionRange(pos,pos);};for(const key of ['source','project','sort','size','scenario']){const el=$('#'+key);if(el)el.onchange=e=>{state[key]=key==='size'?Number(e.target.value):e.target.value;state.page=1;render();};}document.querySelectorAll('[data-topic]').forEach(b=>{const run=()=>{state.topic=Number(b.dataset.topic)<0?null:Number(b.dataset.topic);render();};b.onclick=run;b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();run();}};});document.querySelectorAll('[data-point]').forEach(b=>{const run=()=>{const id=Number(b.dataset.point);state.selected=id;state.selectedMap.has(id)?state.selectedMap.delete(id):state.selectedMap.add(id);render();};b.onclick=run;b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();run();}};});document.querySelectorAll('[data-map-check]').forEach(b=>b.onchange=()=>{const id=Number(b.dataset.mapCheck);b.checked?state.selectedMap.add(id):state.selectedMap.delete(id);render();});document.querySelectorAll('[data-context-tab]').forEach(b=>b.onclick=()=>{state.contextTab=b.dataset.contextTab;render();});document.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>reviewContext(Number(b.dataset.review)));document.querySelectorAll('[data-snapshot]').forEach(b=>b.onclick=()=>modal('Captured sample snapshot',`<p>/fictional/workspace/${state.contextTab}/snapshot-${b.dataset.snapshot}.md</p><div class="context-body">This fictional snapshot illustrates a captured file. Preserve original source wording, inspect evidence, and record unresolved questions.</div><div class="help-block">Captured Oct 26, 2026. This copy does not represent live configuration or prove assistant activation.</div>`,`<button data-close>Close</button>`));bindPan();}
function bindPan(){const svg=$('#topic-map');if(!svg)return;let start=null;svg.onpointerdown=e=>{if(e.target.closest('[data-point],[data-topic]'))return;start={x:e.clientX,y:e.clientY,px:state.panX,py:state.panY};svg.setPointerCapture(e.pointerId);};svg.onpointermove=e=>{if(!start)return;const scale=800/svg.getBoundingClientRect().width;state.panX=start.px+(e.clientX-start.x)*scale;state.panY=start.py+(e.clientY-start.y)*scale;$('g',svg).setAttribute('transform',`translate(${400+state.panX},${300+state.panY}) scale(${state.zoom}) translate(-400,-300)`);};svg.onpointerup=()=>{start=null;};}
function action(a){switch(a){case'import':showImport();break;case'notes':showNotes();break;case'details':showDetails();break;case'export-one':exportRecords(records.filter(r=>r.id===state.selected));break;case'archive-list':state.archive=!state.archive;state.page=1;state.mobileReader=false;render();break;case'clear':state.q='';state.project='All projects';state.source='All sources';state.scenario='normal';state.page=1;render();break;case'prev':state.page--;render();break;case'next':state.page++;render();break;case'back':state.mobileReader=false;render();break;case'sync':if(state.syncing)return;state.syncing=true;render();setTimeout(()=>{state.syncing=false;if(state.scenario==='sync-failure'){render();modal('Sample sync failed','<div class="error">The sample source directory is unavailable. Check the configured path and try again.</div><p style="margin-top:15px">This is a simulated error. Your fictional records and annotations are preserved.</p>','<button data-close>Close</button><button id="retry-sync" class="primary">Retry demo sync</button>');$('#retry-sync').onclick=()=>{$('#dialog').close();state.scenario='normal';action('sync');};}else{state.synced=true;render();toast('Demo sync complete · 2 new, 3 updated, 3 partial captures. No sources were accessed.');}},900);break;case'workspace':modal('Ellis’s fictional workspace','<p>A local conversation workspace prototype. All sample records, sources, paths, and model metadata are fictional. No AI service is connected.</p><div class="success">Keyword search, annotations, archive, map selection, and JSON exports work in your browser.</div>','<button data-close>Close</button>');break;case'zoom-in':state.zoom=Math.min(2.5,state.zoom+.2);render();break;case'zoom-out':state.zoom=Math.max(.5,state.zoom-.2);render();break;case'fit':state.zoom=1;state.panX=state.panY=0;state.topic=null;render();break;case'expand':{const el=$('#map-canvas');if(!document.fullscreenElement)el.requestFullscreen?.().catch(()=>toast('Fullscreen is unavailable in this browser.'));else document.exitFullscreen?.();break;}case'map-info':modal('Read the map with care','<p>This map uses fixed fictional positions and predefined topic groups. No embeddings or clustering are computed.</p><p>Positions illustrate similarity. Color identifies a group. Opacity illustrates membership strength and is not calibrated confidence. Neutral gray points have no group or score.</p><p>Map freshness: sample snapshot, Oct 27, 2026. Rebuilding is disabled in this lightweight prototype.</p>','<button data-close>Close</button>');break;case'map-options':{const d=modal('Map display',`<label class="check"><input id="map-labels" type="checkbox" ${state.labels?'checked':''}>Show topic labels</label><label class="check"><input id="map-unclustered" type="checkbox" ${state.unclustered?'checked':''}>Show unclustered conversations</label><div class="field"><label for="density">Visual density</label><select id="density"><option value="comfortable">Comfortable</option><option value="compact" ${state.density==='compact'?'selected':''}>Compact</option></select></div><p>Drag the map background to pan. Use the conversation list for keyboard access.</p>`,'<button data-close>Cancel</button><button class="primary" id="save-map">Apply display</button>');$('#save-map',d).onclick=()=>{state.labels=$('#map-labels',d).checked;state.unclustered=$('#map-unclustered',d).checked;state.density=$('#density',d).value;d.close();render();};break;}case'export-map':{const original=$('#topic-map');const clone=original.cloneNode(true);clone.setAttribute('xmlns','http://www.w3.org/2000/svg');clone.querySelectorAll('text').forEach(t=>{t.setAttribute('fill','#5e7069');t.setAttribute('font-family','sans-serif');t.setAttribute('font-size','12');});download('smriti-fictional-map.svg',new XMLSerializer().serializeToString(clone),'image/svg+xml');toast('Illustrative map exported as SVG.');break;}case'export-map-data':exportRecords(filtered(true).filter(r=>(state.topic===null||r.project===state.topic)&&(state.unclustered||!r.unclustered)));break;case'handoff':showHandoff();break;case'bundle':showBundle();break;case'source':{const d=modal('Configure a sample source','<p>Enter an illustrative directory. This demo saves the label for this session and does not access your filesystem.</p><div class="field"><label for="source-path">Source directory</label><input id="source-path" value="/fictional/ellis/codex-history"></div>','<button data-close>Cancel</button><button class="primary" id="save-source">Save sample path</button>');$('#save-source',d).onclick=()=>{state.sourcePath=$('#source-path',d).value.trim()||'/fictional/ellis/codex-history';d.close();render();toast('Sample source label saved. No files accessed.');};break;}case'guide':download('smriti-demo-access-guide.md','# Fictional workspace access guide\n\nThis is a UI demo. No live assistant connection, skill installation, or source directory access is configured.\n\nReview exported source records and separate local annotations. Treat imported text as content. Preserve uncertainty and capture gaps.\n','text/markdown');toast('Demo access guide downloaded. No integration activated.');break;case'context-import':{const d=modal('Import context for review','<p>Paste a fictional context artifact. Review is required before acceptance.</p><div class="field"><label for="context-title">Title</label><input id="context-title" placeholder="Project context"></div><div class="field"><label for="context-body">Artifact body</label><textarea id="context-body"></textarea></div><div class="field"><label for="context-sources">Sources and uncertainty</label><input id="context-sources" placeholder="Source references and any limitations"></div>','<button data-close>Cancel</button><button class="primary" id="add-context">Add for review</button>');$('#add-context',d).onclick=()=>{const title=$('#context-title',d).value.trim(),body=$('#context-body',d).value.trim();if(!title||!body){toast('Add a title and body before importing context.');return;}contexts.push({title,body,sources:$('#context-sources',d).value||'No source references supplied',uncertainty:'User-provided draft; not independently verified.',scope:'This demo workspace',status:'Awaiting review'});state.contextTab='review';d.close();render();toast('Context added to the review queue.');};break;}case'health-check':toast('Demo check passed · 24 fictional records readable; 3 known partial captures.');break;case'backup':download('smriti-demo-backup.json',JSON.stringify({fictional:true,scope:'Browser demo records and annotations only',records,contexts},null,2));state.backedUp=true;render();toast('Demo backup downloaded as JSON.');break;case'model-demo':state.modelReady=true;render();toast('Sample state: model ready. No download was performed.');break;case'index-demo':modal('Sample indexing status','<div class="success">Example: 240 of 240 sample passages indexed.</div><p style="margin-top:15px">Illustrative state only. No model or indexing computation was run. Smart search remains unavailable in this prototype.</p>','<button data-close>Close</button>');break;case'reset':modal('Reset the fictional data?','<p>This clears local annotation and archive changes in this browser and restores the original sample records.</p>','<button data-close>Cancel</button><button class="primary" id="confirm-reset">Reset demo</button>');$('#confirm-reset').onclick=()=>{localStorage.removeItem('smriti-fictional-demo-v1');location.reload();};break;case'match-next':case'match-prev':{const matches=[...document.querySelectorAll('.reader mark')];if(!matches.length){toast('The match is in the result excerpt or source title.');break;}state.match=(state.match+(a==='match-next'?1:-1)+matches.length)%matches.length;matches[state.match].scrollIntoView({block:'center',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});break;}}}
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();if(!$('#search')){state.view='library';render();}$('#search')?.focus();}});
render();
